func lengthOfLIS(nums []int) int {
	tails := []int{}
	for _, x := range nums {
		lo, hi := 0, len(tails)
		for lo < hi { // 第一个 >= x 的位置
			mid := (lo + hi) / 2
			if tails[mid] < x {
				lo = mid + 1
			} else {
				hi = mid
			}
		}
		if lo == len(tails) {
			tails = append(tails, x)
		} else {
			tails[lo] = x
		}
	}
	return len(tails)
}

