func longestPalindrome(s string) string {
	if len(s) < 2 {
		return s
	}
	start, best := 0, 1
	for i := 0; i < len(s); i++ {
		for _, c := range [][2]int{{i, i}, {i, i + 1}} {
			l, r := c[0], c[1]
			for l >= 0 && r < len(s) && s[l] == s[r] {
				l--
				r++
			}
			if r-l-1 > best {
				best = r - l - 1
				start = l + 1
			}
		}
	}
	return s[start : start+best]
}

